// This file is generated by AI.

// 自绘下拉选择器。
//
// 为什么不用 Fluent UI 的 `Dropdown`: 它的弹层走 portal + 定位/动画,
// 在 Tauri 的 WebView 中会出现"点击后整块界面变空、再点一下才恢复"的渲染异常
// (见 `main.tsx` 与 `SceneFileDialogs.tsx` 中的同款说明)。
//
// 这里改为**就地展开**的浮层: 挂在字段容器内, 用绝对定位展开, 不使用 portal。
// 配合点击外部关闭与键盘导航, 行为与原生下拉一致。

import { ChevronDownRegular, CheckmarkRegular } from '@fluentui/react-icons';
import { useEffect, useLayoutEffect, useRef, useState } from 'react';

export interface SelectOption {
  value: string;
  label: string;
}

interface Props {
  value: string;
  options: SelectOption[];
  onChange: (value: string) => void;
  /** 无障碍标签与悬浮提示 */
  title?: string;
  disabled?: boolean;
  /** 触发按钮的占位文本 (值为空时显示) */
  placeholder?: string;
  className?: string;
}

/** 弹层与触发按钮的间距 (与样式中的 2px 一致) */
const PANEL_GAP = 2;
/** 弹层露出裁剪边界的最小余量 */
const PANEL_MARGIN = 8;
/** 弹层的理想高度上限 (与样式中的 max-height 一致) */
const PANEL_MAX = 260;
/** 空间不足时的最小可用高度; 再小就先滚动容器腾出空间 */
const PANEL_MIN = 96;

/**
 * 触发按钮上下两个方向的实际可用高度。
 *
 * 不能只看视口: 弹层会被**最近的裁剪祖先**切掉 (工作台的卡片是 `overflow-y: auto`,
 * 角色列表是 `overflow: auto`, 而按 CSS 规范 `overflow-y: auto` 同时把横向也算成裁剪)。
 * 因此这里沿 DOM 向上找出所有会裁剪的祖先, 取其中收得最紧的边界。
 */
function availableSpace(trigger: HTMLElement): { below: number; above: number } {
  const rect = trigger.getBoundingClientRect();
  let top = 0;
  let bottom = window.innerHeight;
  for (let element = trigger.parentElement; element; element = element.parentElement) {
    const style = getComputedStyle(element);
    if (style.overflowY === 'visible' && style.overflowX === 'visible') continue;
    // 这个祖先会裁剪, 用它收窄可用的垂直范围
    const bounds = element.getBoundingClientRect();
    top = Math.max(top, bounds.top);
    bottom = Math.min(bottom, bounds.bottom);
  }
  return {
    below: bottom - rect.bottom - PANEL_GAP - PANEL_MARGIN,
    above: rect.top - top - PANEL_GAP - PANEL_MARGIN,
  };
}

/**
 * 找到一个能滚动的祖先 (用于给弹层腾出空间)。
 *
 * 列表里靠底部的字段下方可能只剩几十像素, 此时朝上朝下都放不下。与其挤成一条缝,
 * 不如把列表滚一点, 把触发按钮挪到能被完整展开的位置。
 */
function scrollableAncestor(element: HTMLElement): HTMLElement | null {
  for (let parent = element.parentElement; parent; parent = parent.parentElement) {
    const style = getComputedStyle(parent);
    const scrollable = /(auto|scroll)/.test(style.overflowY) && parent.scrollHeight > parent.clientHeight + 1;
    if (scrollable) return parent;
  }
  return null;
}

/** 需要时滚动容器, 让触发按钮上下都有足够空间 (返回是否有改动) */
function makeRoom(trigger: HTMLElement, optionsHeight: number): boolean {
  const container = scrollableAncestor(trigger);
  if (!container) return false;
  const { below, above } = availableSpace(trigger);
  if (below >= optionsHeight || above >= optionsHeight) return false;
  const containerRect = container.getBoundingClientRect();
  const rect = trigger.getBoundingClientRect();
  // 目标: 触发按钮上方留出 --above-- 空间, 从而让它落在容器内可完整展开的位置
  const wanted = containerRect.top + PANEL_MARGIN + optionsHeight + rect.height;
  const delta = rect.top - wanted;
  if (delta === 0) return false;
  const before = container.scrollTop;
  container.scrollTop = before + delta;
  return container.scrollTop !== before;
}

export function Select({ value, options, onChange, title, disabled, placeholder, className }: Props) {
  const [open, setOpen] = useState(false);
  const [placement, setPlacement] = useState<'down' | 'up'>('down');
  const [maxHeight, setMaxHeight] = useState(PANEL_MAX);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  /*
   * 弹层高度与方向随可用空间决定。
   *
   * 这里必须做, 不能像普通网页那样只写死 `top: 100%`: 工作台卡片与角色列表都是滚动
   * 容器, 弹层朝下展开会被容器底边直接切掉 (横向也会被切, 因为 `overflow-y: auto`
   * 按规范同时把横向算成裁剪)。因此朝下放不下就朝上, 仍放不下就滚动容器腾空间,
   * 最后按其实际可用空间限高 (超出部分内部滚动)。
   */
  useLayoutEffect(() => {
    if (!open) return;
    const measure = () => {
      const trigger = triggerRef.current;
      if (!trigger) return;
      const wanted = Math.min(PANEL_MAX, options.length * 26 + 8);
      // 先尝试腾空间 (仅在两个方向都放不下时才真的滚动)
      if (makeRoom(trigger, wanted)) return;
      const { below, above } = availableSpace(trigger);
      const nextPlacement = below >= wanted || below >= above ? 'down' : 'up';
      const available = nextPlacement === 'down' ? below : above;
      // 空间实在不够时给一个下限, 宁可略微溢出也不要退化成一条缝
      setPlacement(nextPlacement);
      setMaxHeight(Math.max(PANEL_MIN, Math.min(PANEL_MAX, available)));
    };
    measure();
    // 面板出现后布局可能变化, 再量一次
    const frame = requestAnimationFrame(measure);
    const onScrollOrResize = () => measure();
    window.addEventListener('resize', onScrollOrResize);
    // 捕获阶段: 容器内部滚动不会冒泡到 window
    window.addEventListener('scroll', onScrollOrResize, true);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener('resize', onScrollOrResize);
      window.removeEventListener('scroll', onScrollOrResize, true);
    };
  }, [open]);

  // 点击外部 / Esc 关闭
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      const root = rootRef.current;
      if (root && !root.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false);
    };
    window.addEventListener('pointerdown', onPointerDown, true);
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('pointerdown', onPointerDown, true);
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [open]);

  const current = options.find((option) => option.value === value);
  const label = current?.label ?? placeholder ?? value;

  return (
    <div className={`select${className ? ` ${className}` : ''}${open ? ' open' : ''}`} ref={rootRef}>
      <button
        type="button"
        ref={triggerRef}
        className="select-trigger"
        title={title ?? label}
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <span className="select-label">{label}</span>
        <ChevronDownRegular className="select-chevron" />
      </button>

      {open && (
        <div className={`select-panel select-panel-${placement}`} role="listbox" style={{ maxHeight }}>
          {options.map((option) => {
            const selected = option.value === value;
            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={selected}
                className={`select-option${selected ? ' selected' : ''}`}
                title={option.label}
                onClick={() => {
                  onChange(option.value);
                  setOpen(false);
                }}
              >
                <span className="select-option-check">{selected ? <CheckmarkRegular /> : null}</span>
                <span className="select-option-label">{option.label}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/** 由 `Record<string, string>` 构造选项 (键序即显示顺序) */
export function toOptions(labels: Record<string, string>): SelectOption[] {
  return Object.entries(labels).map(([value, label]) => ({ value, label }));
}
